Here's a real world example (ask me how I know) where the promise case can bite you. The fix is simple if you're aware of this landmine, but it is easy to miss and get misled by TS trying to be "helpful".

```TypeScript
const MyComponent: FC = () => {
   const canvasRef = useRef<HTMLCanvasElement>(null);
   useEffect(() => {
      void (async () => {
         if (!canvasRef.current) {
            return;
         }

         // this is correct - canvasRef.current is guaranteed to be non-null
         canvasRef.current.getContext('2d')?.clearRect(0, 0, canvasRef.current.width, canvasRef.current.height);

         // any async func that can take a while
         await new Promise(r => setTimeout(r, 5000));

         // This might totally blow up - canvasRef.current can be null. But TS assures me it isn't.
         canvasRef.current.getContext('2d')?.rect(0, 0, 10, 10);
      })();
   }, []);

   return (
      <canvas ref={canvasRef} />
   );
};
```

